<p class="lead">Donation, collection, deadline and account messages for your account.</p>
<?php if (!$data['notifications']): ?><p class="empty-state">You’re all caught up. New activity will appear here.</p><?php endif ?>
<?php foreach ($data['notifications'] as $notification): ?><article class="panel spaced"><div class="card-top"><h2><?= e($notification['title']) ?></h2><?php badge($notification['read_at'] ? 'read' : 'unread'); ?></div><p><?= e($notification['message']) ?></p><p class="muted"><?php stamp($notification['created_at']); ?></p><div class="page-actions"><a class="underlined" href="<?= e($notification['link']) ?>">View details →</a><?php if (!$notification['read_at']): ?><form data-api="/api/notifications/read"><input type="hidden" name="id" value="<?= e($notification['id']) ?>"><?php formend('Mark as read'); ?><?php endif ?></div></article><?php endforeach ?>
